//! 🧳️ Native receiving keeps its exact original source until the receiver and staged output settle.
use super::{NativeReceive,NativeReceiver};
use crate::{NativeDecodeControl,RetirementDemand,ValueError,ValueRefusalKind,retirement::{RetireOwned,RetirementCursor,RetirementStep},retained_clone::{RetainedCloneSource,RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
/// 🪪️ The registered codec supplies its genuine typed input source and required receiver without a cold conversion.
pub struct NativeReceivingOriginal<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync=I>{original:ManuallyDrop<Option<RetainedCloneSource<I,A>>>,receiver:semio_framework_value_native_storage::NativeOwnedStorage<T::Receiver>,retired_header:Option<Box<T::Receiver>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,closing:bool}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native original receiving is not in the required funded phase")}
fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn receipt(copy_bytes:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:copy_bytes,..Default::default()}}
fn nested(mut d:RetirementDemand,copy:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(copy).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> NativeReceivingOriginal<I,T,A>{
 pub fn new(original:RetainedCloneSource<I,A>)->Self{Self{original:ManuallyDrop::new(Some(original)),receiver:semio_framework_value_native_storage::NativeOwnedStorage::empty(),retired_header:None,output:ManuallyDrop::new(None),retirement:Default::default(),closing:false}}
 pub fn borrow_input(&self)->Result<RetainedCloneRef<'_,I>,ValueError>{if self.closing{return Err(invalid())}self.original.as_ref().ok_or_else(invalid)?.try_borrow()}
 pub fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}if !self.receiver.reserved(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::reserve_demand())}if !self.receiver.initialized(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::move_demand())}let receiver=self.receiver.get().unwrap();nested(if receiver.output_ready(){receiver.take_demand()?}else{receiver.demands(self.borrow_input()?,body)?},0)}
 pub fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{let mut work=0;let result:Result<RetainedCloneStep,crate::OriginalReceivingPrimary>=(||{let d=self.demands(body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?;if !self.receiver.reserved(){let turn=self.receiver.reserve(g);let turn=control.receive_retained_work(g,turn);work=turn.work;return turn.result.map_err(Into::into)}if !self.receiver.initialized(){let turn={let mut header=Some(T::receiver());self.receiver.put_from(&mut header,g)};work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)}let receiver=self.receiver.get_mut().unwrap();let child=RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g};if receiver.output_ready(){let turn=receiver.take(child);work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.output=Some(value);return Ok(RetainedCloneStep::Complete(p))}let turn=receiver.advance(self.original.as_ref().ok_or_else(invalid)?.try_borrow()?,control,body,child);work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)})();crate::RetainedWorkOutcome{result,work}}
 pub fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(fixed(0))}
 pub fn take(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<(T,RetainedCloneProgress)>>{let mut work=0;let result=(||{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None)}work=1;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(0))))})();crate::RetainedWorkOutcome{result,work}}
 pub fn begin_close(&mut self){self.closing=true;if let Some(receiver)=self.receiver.get_mut(){receiver.begin_close()}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.receiver.reserved()||self.retired_header.is_some(){return super::native_receiver_backing_demands::<I,T,_>(&self.receiver,&self.retired_header,body)}if !self.retirement.is_empty(){return nested(self.retirement.next_owner_demands::<T>(false,&None,body)?,0)}if self.output.is_some(){return nested(self.retirement.next_owner_demands::<T>(true,&None,body)?,0)}if let Some(original)=self.original.as_ref(){return if original.terminal_is_empty(){Ok(fixed(0))}else{nested(original.next_close_demand(body)?,0)}}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->crate::RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};if self.receiver.reserved()||self.retired_header.is_some(){let turn=if let Some(receiver)=self.receiver.get_mut().filter(|receiver|!receiver.terminal_is_empty()){receiver.close_step(child)}else{super::close_native_receiver_backing::<I,T,_>(&mut self.receiver,&mut self.retired_header,g)};work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(child);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,child);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if let Some(original)=self.original.as_mut(){if !original.terminal_is_empty(){let turn=original.close_step(child);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}work=1;self.original.take();return Ok(RetainedCloneStep::Complete(receipt(0)))}Ok(RetainedCloneStep::Complete(Default::default()))})();crate::RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.receiver.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.original.is_none()}
}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetireOwned for NativeReceivingOriginal<I,T,A>{fn retirement(mut self)->Box<dyn RetirementCursor>{self.begin_close();Box::new(self)}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<Self>())}fn controlled_retirement_supported()->bool{true}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> RetirementCursor for NativeReceivingOriginal<I,T,A>{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close_demands(body)}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{let turn=Self::close_step(self,g);match turn.result{Ok(s)=>RetirementStep::Progress(s.progress(),turn.work),Err(error)=>RetirementStep::Failure(error,turn.work)}}fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}fn terminal_release_bytes(&self)->Option<usize>{Some(size_of::<Self>())}}
impl<I:Sync+'static,T:NativeReceive<I>,A:RetireOwned+Sync> Drop for NativeReceivingOriginal<I,T,A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native receiving keeps original custody until funded closure");}}
